const b = $json.body ?? {};
const h = $json.headers ?? {};
const message = typeof b.message === 'string' ? b.message : '';
const sessionId = typeof b.session_id === 'string' ? b.session_id : '';
const locale = b.locale === 'en' ? 'en' : 'id';
const localeOk = b.locale === undefined || b.locale === '' || b.locale === 'id' || b.locale === 'en';
const valid = message.length >= 1 && message.length <= 1000 && sessionId.length >= 1 && sessionId.length <= 64 && localeOk;
const auth = typeof h.authorization === 'string' ? h.authorization : '';
const token = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
const xff = typeof h['x-forwarded-for'] === 'string' ? h['x-forwarded-for'].split(',')[0].trim() : '';
return [{ json: { valid, message, session_id: sessionId, locale, token, ip: xff || 'unknown' } }];

const v = $('Validasi').first().json;
const j = $json ?? {};
const p = j.error ? null : (j.payload ?? j);
const userId = p && typeof p.sub === 'string' && p.sub ? p.sub : null;
const email = userId && typeof p.email === 'string' ? p.email : null;
const bucket = userId ? 'user:' + userId : 'ip:' + v.ip;
return [{ json: { user_id: userId, email, locale: v.locale, session_id: v.session_id, message: v.message, bucket_key: bucket, limit: userId ? 60 : 20 } }];
